def prime_fib(n: int):
    """
    prime_fib returns n-th number that is a Fibonacci number and it's also prime.
    >>> prime_fib(1)
    2
    >>> prime_fib(2)
    3
    >>> prime_fib(3)
    5
    >>> prime_fib(4)
    13
    >>> prime_fib(5)
    89
    """
    assert n >= 1, "n must be greater than 0"
    assert isinstance(n, int), "n must be integer"
    assert n <= 100000, "n must be less than 100000"

    def is_prime(n: int) -> bool:
        if n < 2:
            return False
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                return False
        return True

    def fib(n: int) -> int:
        if n == 0:
            return 0
        if n == 1:
            return 1
        return fib(n - 1) + fib(n - 2)

    def fib_prime(n: int) -> int:
        i = 0
        while True:
            if fib(i) % 2 == 0:
                i += 1
            else:
                if is_prime(fib(i)):
                    if n == 1:
                        return fib(i)
                    else:
                        n -= 1
                        i += 1
    return fib_prime(n)

